package com.asisten.bantu;
import android.os.Bundle; import android.os.Handler; import android.os.Looper; import android.speech.RecognitionListener; import android.speech.RecognizerIntent; import android.speech.SpeechRecognizer; import android.speech.tts.TextToSpeech; import android.widget.Button; import android.widget.TextView; import java.util.*;
public class AiChatActivity extends AppCompatActivity implements TextToSpeech.OnInitListener {
    private TextView tvHistory; private TextToSpeech tts; private SpeechRecognizer recognizer; private android.content.Intent recognizerIntent; private Handler handler = new Handler(Looper.getMainLooper()); private StringBuilder chatLog = new StringBuilder(); private Map<String, String> knowledgeBase;
    @Override protected void onCreate(Bundle savedInstanceState) { super.onCreate(savedInstanceState); setContentView(R.layout.activity_ai_chat); tvHistory = findViewById(R.id.tvChatHistory); Button btnListen = findViewById(R.id.btnListenChat); Button btnClose = findViewById(R.id.btnCloseChat); tts = new TextToSpeech(this, this); buildKnowledgeBase(); chatLog.append("Kobra AI: Halo Tuan! Saya Kobra AI teman ngobrol offline anda. Tanya apa saja: motivasi, doa, info, curhat.\n\n"); tvHistory.setText(chatLog.toString()); btnListen.setOnClickListener(v -> startListening()); btnClose.setOnClickListener(v -> finish()); initRecognizer(); }
    private void buildKnowledgeBase() { knowledgeBase = new HashMap<>(); knowledgeBase.put("sedih", "Saya mengerti anda sedih Tuan. Setiap kesulitan pasti ada kemudahan. Anda tidak sendiri, Kobra selalu di sini jadi mata dan teman anda."); knowledgeBase.put("semangat", "Semangat Tuan! Anda luar biasa sudah berjuang sampai sejauh ini. Kobra bangga jadi mata anda!"); knowledgeBase.put("sholat", "Waktu sholat: Subuh 04:30, Dzuhur 12:00, Ashar 15:00, Maghrib 18:00, Isya 19:00. Jangan lupa sholat Tuan."); knowledgeBase.put("lelucon", "Kenapa kucing tidak pernah main HP? Karena takut kehabisan pulsa... kucing! Haha"); knowledgeBase.put("siapa kamu", "Saya Kobra OS V6, sistem operasi mata super untuk tunanetra. Bisa baca uang, warna, orang, KTP, mode tongkat, SOS, dan teman ngobrol AI offline."); knowledgeBase.put("terima kasih", "Sama-sama Tuan! Senang bisa membantu. Kobra selalu siap jadi mata anda."); }
    private void initRecognizer() { recognizer = SpeechRecognizer.createSpeechRecognizer(this); recognizer.setRecognitionListener(new RecognitionListener() { @Override public void onReadyForSpeech(Bundle b) {} @Override public void onBeginningOfSpeech() {} @Override public void onRmsChanged(float v) {} @Override public void onBufferReceived(byte[] b) {} @Override public void onEndOfSpeech() {} @Override public void onError(int e) {} @Override public void onResults(Bundle results) { ArrayList<String> matches = results.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION); if (matches != null && !matches.isEmpty()) { String spoken = matches.get(0).toLowerCase(); handleChat(spoken); } } @Override public void onPartialResults(Bundle b) {} @Override public void onEvent(int e, Bundle b) {} }); recognizerIntent = new android.content.Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH); recognizerIntent.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM); recognizerIntent.putExtra(RecognizerIntent.EXTRA_LANGUAGE, "id-ID"); recognizerIntent.putExtra(RecognizerIntent.EXTRA_PREFER_OFFLINE, true); }
    private void startListening() { try { tvHistory.append("\n🎤 Mendengarkan...\n"); recognizer.startListening(recognizerIntent); } catch (Exception e) {} }
    private void handleChat(String input) { chatLog.append("Anda: ").append(input).append("\n"); String response = generateResponse(input); chatLog.append("Kobra AI: ").append(response).append("\n\n"); tvHistory.setText(chatLog.toString()); speak(response); }
    private String generateResponse(String input) { input = input.toLowerCase(); for (Map.Entry<String, String> entry : knowledgeBase.entrySet()) { if (input.contains(entry.getKey())) return entry.getValue(); } if (input.contains("halo") || input.contains("hai")) return "Halo Tuan! Senang dengar suara anda. Ada yang bisa Kobra bantu?"; if (input.contains("jam berapa")) { java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("HH:mm", Locale.getDefault()); return "Sekarang jam " + sdf.format(new Date()) + " Tuan."; } return "Menarik Tuan, anda bilang: " + input + ". Bisa ceritakan lebih detail? Tanya motivasi, cara pakai Kobra, lelucon, doa, atau curhat apa saja."; }
    private void speak(String s) { if (tts != null) tts.speak(s, TextToSpeech.QUEUE_FLUSH, null, null); }
    @Override public void onInit(int status) { if (status == TextToSpeech.SUCCESS) { tts.setLanguage(new Locale("id","ID")); tts.setSpeechRate(0.9f); speak("Halo Tuan! Saya Kobra AI teman ngobrol offline anda."); } }
    @Override protected void onDestroy() { if (recognizer != null) recognizer.destroy(); if (tts != null) { tts.stop(); tts.shutdown(); } super.onDestroy(); }
}
